import { JSDOM } from 'jsdom';
import axeSource from 'axe-core/axe.min.js';

/**
 * Run axe-core plus custom checks against an HTML string.
 *
 * @param {string} html - Full HTML document or fragment.
 * @returns {Promise<{violations: Array, custom: Array<{id: string, target: string[], message: string}>}>}
 */
export async function auditHtml(html) {
  const dom = new JSDOM(html, { pretendToBeVisual: true });
  const { window } = dom;
  const { document } = window;

  try {
    // Execute axe-core inside the jsdom window context.
    // eslint-disable-next-line no-new-func
    const runAxe = new Function(
      'window', 'document',
      `${axeSource}\n;return window.axe;`
    );
    const axe = runAxe(window, document);

    const results = await axe.run(document, {
      resultTypes: ['violations'],
    });

    const violations = results.violations.map((v) => ({
      id: v.id,
      impact: v.impact,
      nodes: v.nodes.map((n) => ({
        target: n.target,
        html: n.html,
      })),
    }));

    const custom = [
      ...findHeadingSkips(document),
      ...findFakeButtons(document),
    ];

    return { violations, custom };
  } finally {
    // Close the jsdom window cleanly so timers/resources are released
    // and vitest can tear down without open handles.
    await new Promise((resolve) => {
      window.close();
      // jsdom's close() is sync for our purposes but give the event
      // loop a tick to flush any pending teardown.
      setTimeout(resolve, 0);
    });
  }
}

/**
 * Custom check 1: heading-level skips anywhere in the document.
 * A skip is a jump from heading level n to level > n + 1 (e.g. h1 -> h3).
 * Returns one finding per offending heading.
 */
export function findHeadingSkips(document) {
  const findings = [];
  let prevLevel = null;

  for (const h of document.querySelectorAll('h1,h2,h3,h4,h5,h6')) {
    const level = Number(h.tagName[1]);
    if (prevLevel !== null && level > prevLevel + 1) {
      findings.push({
        id: 'custom/heading-skip',
        target: [selectorFor(h)],
        message: `Heading level skipped from h${prevLevel} to h${level}`,
      });
    }
    prevLevel = level;
  }

  return findings;
}

/**
 * Custom check 2: elements whose class contains "btn" that behave like a
 * button but are not <button>, links with href, or otherwise focusable
 * (input/select/textarea, tabindex >= 0, contenteditable).
 */
export function findFakeButtons(document) {
  const findings = [];

  for (const el of document.querySelectorAll('[class*=btn i], [class*=Btn i]')) {
    const tag = el.tagName.toLowerCase();

    if (tag === 'button') continue;

    if ((tag === 'a' || tag === 'area') && el.hasAttribute('href')) continue;

    if (['input', 'select', 'textarea'].includes(tag)) continue;

    const tabIndex = parseInt(el.getAttribute('tabindex') ?? '', 10);
    const isFocusable =
      (!Number.isNaN(tabIndex) && tabIndex >= 0) ||
      el.hasAttribute('contenteditable');

    if (isFocusable) continue;

    findings.push({
      id: 'custom/fake-button',
      target: [selectorFor(el)],
      message:
        `Element with click-suggesting class "${el.getAttribute('class')}" ` +
        `is not a button, link, or focusable element`,
    });
  }

  return findings;
}

/** Build a stable CSS-ish selector for reporting. */
function selectorFor(el) {
  if (el.id) return `#${el.id}`;
  let selector = el.tagName.toLowerCase();
  for (const cls of el.classList) {
    selector += `.${CSS.escape(cls)}`;
  }
  if (el.parentElement) {
    const index =
      Array.from(el.parentElement.children).indexOf(el) + 1;
    selector += `:nth-child(${index})`;
  }
  return selector;
}

