import { describe, it, expect } from 'vitest';
import { auditHtml } from '../src/audit.js';

// ---------------------------------------------------------------------------
// Fixtures (inline)
// ---------------------------------------------------------------------------

const BAD_HTML = `<!DOCTYPE html>
<html lang="en">
  <head><title>Bad page</title></head>
  <body>
    <main>
      <h1>Shipping &amp; Billing</h1>
      <h3>Billing address</h3>
      <img src="logo.png">
      <div class="btn btn-primary" role="none">Submit order</div>
      <div class="btn-toolbar" tabindex="-1">Toolbar</div>
    </main>
  </body>
</html>`;

const GOOD_HTML = `<!DOCTYPE html>
<html lang="en">
  <head><title>Good page</title></head>
  <body>
    <main>
      <h1>Checkout</h1>
      <h2>Shipping address</h2>
      <h3>Delivery options</h3>
      <button class="btn btn-primary" type="button">Place order</button>
      <a href="/cart" class="btn-link">View cart</a>
      <img src="logo.png" alt="Shop logo">
    </main>
  </body>
</html>`;

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('auditHtml', () => {
  it('flags the known-bad fixture with exact rule ids and custom findings', async () => {
    const report = await auditHtml(BAD_HTML);

    // axe violations: image without alt. The skipped heading and fake
    // button are covered by our custom checks instead.
    const axeIds = report.violations.map((v) => v.id).sort();
    expect(axeIds).toEqual(['image-alt']);

    // Custom findings: heading skip (h1 -> h3) + two fake buttons.
    expect(report.custom).toHaveLength(2);

    const ids = report.custom.map((f) => f.id);
    expect(ids).toContain('custom/heading-skip');
    expect(ids).toContain('custom/fake-button');

    const skip = report.custom.find((f) => f.id === 'custom/heading-skip');
    expect(skip.target[0]).toContain('h3');
    expect(skip.message).toMatch(/h1 to h3/);

    const fake = report.custom.find((f) => f.id === 'custom/fake-button');
    // Only the div without tabindex is flagged; tabindex="-1" is not
    // focusable via keyboard interaction but our check only skips
    // tabindex >= 0... see implementation: -1 IS flagged.
    expect(fake.target[0]).toContain('btn');
  });

  it('returns empty arrays for the known-good fixture', async () => {
    const report = await auditHtml(GOOD_HTML);
    expect(report.violations).toEqual([]);
    expect(report.custom).toEqual([]);
  });

  it('closes the jsdom window cleanly (no dangling handles)', async () => {
    const { JSDOM } = await import('jsdom');
    let windowRef;
    const spy = vi.spyOn({ JSDOM }, 'JSDOM');
    spy.mockImplementation((...args) => {
      const dom = new JSDOM(...args);
      windowRef = dom.window;
      return dom;
    });
    try {
      await auditHtml('<html><body><p>hi</p></body></html>');
      expect(windowRef.closed).toBe(true);
    } finally {
      spy.mockRestore();
    }
  });
});

