<html lang="en">
  <head><title>Bad page</title></head>
  <body>
    <main>
      <h1>Shipping &amp; Billing</h1>
      <h3>Billing address</h3>
      <img src="logo.png">
      <div class="btn btn-primary">Submit order</div>
      <div class="btn-toolbar" tabindex="-1">Toolbar</div>
    </main>
  </body>
</html>`;

const GOOD_HTML = `<!DOCTYPE html>
<html lang="en">
  <head><title>Good page</title></head>
  <body>
    <main>
      <h1>Checkout</h1>
      <h2>Shipping address</h2>
      <h3>Delivery options</h3>
      <button class="btn btn-primary" type="button">Place order</button>
      <a href="/cart" class="btn-link">View cart</a>
      <input type="text" class="btn-input" value="x">
      <div class="btn-editable" tabindex="0" role="button">Editable control</div>
      <img src="logo.png" alt="Shop logo">
    </main>
  </body>
</html>`;

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('auditHtml', () => {
  afterEach(() => vi.restoreAllMocks());

  it('flags the known-bad fixture with exactly the expected rule ids and custom findings', async () => {
    const report = await auditHtml(BAD_HTML);

    // axe catches the image without alt; the skipped heading and fake
    // buttons are covered by our hand-written checks.
    expect(report.violations.map((v) => v.id)).toEqual(['image-alt']);

    // One heading-skip (h1 -> h3) + two fake buttons.
    // tabindex="-1" does not make an element keyboard-focusable, so the
    // btn-toolbar div is still flagged.
    expect(report.custom).toHaveLength(3);

    const skips = report.custom.filter((f) => f.id === 'custom/heading-skip');
    expect(skips).toHaveLength(1);
    expect(skips[0].target[0]).toContain('h3');
    expect(skips[0].message).toMatch(/h1 to h3/);

    const fakes = report.custom.filter((f) => f.id === 'custom/fake-button');
    expect(fakes).toHaveLength(2);
    expect(fakes[0].target[0]).toContain('.btn');
    expect(fakes[1].target[0]).toContain('.btn-toolbar');
  });

  it('returns empty arrays for the known-good fixture', async () => {
    const report = await auditHtml(GOOD_HTML);
    expect(report.violations).toEqual([]);
    expect(report.custom).toEqual([]);
  });

  it('closes the jsdom window cleanly', async () => {
    const jsdom = await import('jsdom');
    const closeSpy = vi.spyOn(jsdom.Window.prototype, 'close');

    const report = await auditHtml('<html><body><p>hi</p></body></html>');
    expect(closeSpy).toHaveBeenCalledOnce();
    closeSpy.mockRestore();

    // Report shape sanity for a trivial document.
    expect(report.violations).toEqual([]);
    expect(report.custom).toEqual([]);
  });
});
"})
